var commands = (Console.ReadLine() ?? "").Trim().Split(' ');
if (commands.Length > 50) Environment.Exit(1);
var stack = new MyStack<int>();
foreach (var command in commands)
{
    if (command.Length == 0) Environment.Exit(1);
    if (command.StartsWith("push:"))
    {
        if (!int.TryParse(command[5..], out var item)) Environment.Exit(1);
        stack.Push(item);
    }
    else if (command == "pop")
    {
        try
        {
            Console.WriteLine("pop=" + stack.Pop());
        }
        catch (InvalidOperationException)
        {
            Console.WriteLine("error=empty");
            return;
        }
    }
    else if (command == "peek")
    {
        try
        {
            Console.WriteLine("peek=" + stack.Peek());
        }
        catch (InvalidOperationException)
        {
            Console.WriteLine("error=empty");
            return;
        }
    }
    else if (command == "count")
    {
        Console.WriteLine("count=" + stack.Count);
    }
    else
    {
        Environment.Exit(1);
    }
}

sealed class MyStack<T>
{
    private readonly List<T> _items = new();

    public int Count => _items.Count;

    public void Push(T item) => _items.Add(item);

    public T Pop()
    {
        if (_items.Count == 0) throw new InvalidOperationException();
        var item = _items[^1];
        _items.RemoveAt(_items.Count - 1);
        return item;
    }

    public T Peek()
    {
        if (_items.Count == 0) throw new InvalidOperationException();
        return _items[^1];
    }
}
